# 31_meta_truth.R: tables for the generator (niches, dominance) and the Monte Carlo ecological truth (R = 200 simulated communities per matched profile). Run from final/ (ZG_LIB6 set).
source("revision_ident/30_meta_common.R"); write.csv(SP, "revision_ident/tables/meta_species.csv", row.names = FALSE); xg <- seq(0, 1, length.out = 101)
write.csv(bind_rows(lapply(MSCN, function(s) data.frame(scenario = s, P = xg, generalist_dominance = pi_gen(xg, s)))), "revision_ident/tables/meta_guild_dominance.csv", row.names = FALSE)
nich <- expand.grid(X = xg, i = 1:200); nich$niche <- exp(-.5 * ((nich$X - SP$opt[nich$i]) / SP$sd[nich$i])^2) * SP$a[nich$i]; nich$guild <- SP$guild[nich$i]; nich$species <- SP$species[nich$i]; write.csv(nich[, c("species", "guild", "X", "niche")], "revision_ident/tables/meta_niche_curves.csv", row.names = FALSE)
library(parallel); jobs <- expand.grid(scn = MSCN, k = c(2, 3, 4, 5, 8), stringsAsFactors = FALSE); T_ <- bind_rows(mclapply(split(jobs, seq_len(nrow(jobs))), function(z) mc_truth(z$scn, z$k), mc.cores = 9)); write.csv(T_, "revision_ident/tables/meta_truth_surfaces.csv", row.names = FALSE)
options(width = 200, digits = 3); print(T_ |> filter(order == 2, m == .5, abs(h - .3) < 1e-9 | abs(h - .1) < 1e-9) |> select(scenario, h, Pm, relative, incidence) |> tidyr::pivot_wider(names_from = h, values_from = c(relative, incidence)) |> as.data.frame())
